use crate::{
    ProviderInfo,
    http::Operation,
    resource::{CredentialSource, ManagedResource, ResourceDescriptor},
};
use k8s_openapi::apiextensions_apiserver::pkg::apis::apiextensions::v1::CustomResourceDefinition;
use serde_json::Value;
use std::{fmt::Write as _, fs, io, path::Path};

const HEADER: &str =
    "<!-- Generated by koof from the provider's CRDs. Do not edit manually. -->\n\n";

pub struct ResourceDoc {
    descriptor: &'static ResourceDescriptor,
    crd: Value,
    operations: Vec<(&'static str, reqwest::Method, &'static str)>,
}

impl ResourceDoc {
    #[must_use]
    pub fn of<R: ManagedResource + kube::CustomResourceExt>() -> Self {
        let descriptor = R::descriptor();
        let mut operations = vec![("observe", R::Observe::METHOD, R::Observe::PATH)];
        if descriptor.create.is_some() {
            operations.push(("create", R::Create::METHOD, R::Create::PATH));
        }
        if descriptor.update.is_some() {
            operations.push(("update", R::Update::METHOD, R::Update::PATH));
        }
        if descriptor.delete.is_some() {
            operations.push(("delete", R::Delete::METHOD, R::Delete::PATH));
        }
        Self {
            descriptor,
            crd: crd_value(&R::crd()),
            operations,
        }
    }

    fn version(&self) -> &str {
        self.crd
            .pointer("/spec/versions/0/name")
            .and_then(Value::as_str)
            .unwrap_or_default()
    }

    fn api_version(&self) -> String {
        format!("{}/{}", self.descriptor.group, self.version())
    }

    fn file(&self) -> String {
        format!(
            "{}_{}_{}.md",
            self.descriptor.group,
            self.version(),
            self.descriptor.kind.to_lowercase()
        )
    }

    fn schema(&self, property: &str) -> Option<&Value> {
        self.crd.pointer(&format!(
            "/spec/versions/0/schema/openAPIV3Schema/properties/{property}"
        ))
    }
}

fn crd_value(crd: &CustomResourceDefinition) -> Value {
    serde_json::to_value(crd).unwrap_or_default()
}

/// Writes `README.md` (a table of every kind) and `docs/<group>_<version>_<kind>.md`
/// (operations, an example and every field) into `directory`, replacing `docs/`.
///
/// # Errors
///
/// Returns an error when a file cannot be written.
pub fn write(
    directory: &Path,
    provider: &ProviderInfo,
    resources: &[ResourceDoc],
) -> io::Result<()> {
    let docs = directory.join("docs");
    if docs.exists() {
        fs::remove_dir_all(&docs)?;
    }
    fs::create_dir_all(&docs)?;
    fs::write(directory.join("README.md"), readme(provider, resources))?;
    for resource in resources {
        fs::write(docs.join(resource.file()), page(resource))?;
    }
    Ok(())
}

#[must_use]
pub fn readme(provider: &ProviderInfo, resources: &[ResourceDoc]) -> String {
    let mut out = format!(
        "{HEADER}# koof-{name}\n\nA Kubernetes operator for `{base_url}`, generated by koof: every kind \
         below is a managed resource whose `spec.forProvider` is kept in sync with the API.\n\n\
         | Kind | API version | Scope | Operations | References | Credentials |\n\
         |---|---|---|---|---|---|\n",
        name = provider.name,
        base_url = provider.base_url,
    );
    let mut sorted: Vec<&ResourceDoc> = resources.iter().collect();
    sorted.sort_by_key(|resource| (resource.descriptor.group, resource.descriptor.kind));
    for resource in sorted {
        let descriptor = resource.descriptor;
        let operations: Vec<&str> = resource.operations.iter().map(|(name, ..)| *name).collect();
        let _ = writeln!(
            out,
            "| [{kind}](docs/{file}) | `{api_version}` | {scope} | {operations} | {references} | {credentials} |",
            kind = descriptor.kind,
            file = resource.file(),
            api_version = resource.api_version(),
            scope = scope(descriptor),
            operations = operations.join(", "),
            references = references(descriptor).join(", "),
            credentials = credentials(descriptor),
        );
    }
    out
}

fn scope(descriptor: &ResourceDescriptor) -> &'static str {
    if descriptor.namespaced {
        "Namespaced"
    } else {
        "Cluster"
    }
}

fn references(descriptor: &ResourceDescriptor) -> Vec<String> {
    descriptor
        .references
        .iter()
        .map(|reference| {
            let field = reference
                .from
                .rsplit(['.', '/'])
                .next()
                .unwrap_or(reference.from);
            let kinds: Vec<&str> = reference.targets.iter().map(|target| target.kind).collect();
            format!("`{field}` → {}", kinds.join(" / "))
        })
        .collect()
}

fn credentials(descriptor: &ResourceDescriptor) -> String {
    match descriptor
        .credentials
        .as_ref()
        .map(|credentials| &credentials.source)
    {
        Some(CredentialSource::Secret { path }) => {
            format!(
                "Secret `{}`",
                path.rsplit(['.', '/']).next().unwrap_or(path)
            )
        }
        Some(CredentialSource::Related { via }) => format!("via {}", via.join(" → ")),
        None => "–".to_owned(),
    }
}

fn page(resource: &ResourceDoc) -> String {
    let descriptor = resource.descriptor;
    let mut out = format!(
        "{HEADER}# {kind}\n\n`{api_version}` · {scope} · [all resources](../README.md)\n\n\
         | Operation | Request |\n|---|---|\n",
        kind = descriptor.kind,
        api_version = resource.api_version(),
        scope = scope(descriptor),
    );
    for (name, method, path) in &resource.operations {
        let _ = writeln!(out, "| {name} | `{method} {path}` |");
    }
    let references = references(descriptor);
    if !references.is_empty() {
        let _ = write!(out, "\nReferences: {}.\n", references.join(", "));
    }
    let _ = write!(out, "\nCredentials: {}.\n", credentials(descriptor));

    let _ = write!(out, "\n## Example\n\n```yaml\n{}```\n", example(resource));

    out.push_str("\n## Spec\n\n");
    if let Some(spec) = resource.schema("spec") {
        out.push_str(&fields(spec, ""));
    }
    out.push_str(
        "\n## Status\n\n`conditions` holds `Ready` and `Synced`; `atProvider` is the resource as \
         the API returns it.\n\n",
    );
    if let Some(at_provider) = resource
        .schema("status")
        .and_then(|status| status.pointer("/properties/atProvider"))
    {
        out.push_str(&fields(at_provider, "atProvider"));
    }
    out
}

fn example(resource: &ResourceDoc) -> String {
    let mut out = format!(
        "apiVersion: {}\nkind: {}\nmetadata:\n  name: example\n",
        resource.api_version(),
        resource.descriptor.kind
    );
    if let Some(for_provider) = resource
        .schema("spec")
        .and_then(|spec| spec.pointer("/properties/forProvider"))
    {
        out.push_str("spec:\n  forProvider:\n");
        let extra: Vec<String> = resource
            .descriptor
            .references
            .iter()
            .map(|reference| {
                reference
                    .from
                    .rsplit(['.', '/'])
                    .next()
                    .unwrap_or(reference.from)
                    .to_owned()
            })
            .chain(
                match resource.descriptor.credentials.as_ref().map(|c| &c.source) {
                    Some(CredentialSource::Secret { path }) => {
                        path.rsplit(['.', '/']).next().map(str::to_owned)
                    }
                    _ => None,
                },
            )
            .collect();
        example_object(&mut out, for_provider, &extra, 4);
    }
    out
}

fn example_object(out: &mut String, schema: &Value, extra: &[String], indent: usize) {
    let required = names(schema.get("required"));
    let Some(properties) = schema.get("properties").and_then(Value::as_object) else {
        return;
    };
    for (name, property) in properties {
        if !required.contains(&name.as_str()) && !extra.contains(name) {
            continue;
        }
        let pad = " ".repeat(indent);
        if property.get("properties").is_some() {
            let _ = writeln!(out, "{pad}{name}:");
            example_object(out, property, &[], indent + 2);
        } else {
            let _ = writeln!(out, "{pad}{name}: {}", placeholder(name, property));
        }
    }
}

fn placeholder(name: &str, schema: &Value) -> String {
    if let Some(first) = schema.get("enum").and_then(|values| values.get(0)) {
        return first.to_string();
    }
    match schema.get("type").and_then(Value::as_str) {
        Some("integer" | "number") => "0".to_owned(),
        Some("boolean") => "false".to_owned(),
        Some("array") => "[]".to_owned(),
        Some("object") => "{}".to_owned(),
        _ => format!("<{name}>"),
    }
}

fn names(value: Option<&Value>) -> Vec<&str> {
    value
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .collect()
}

fn fields(schema: &Value, root: &str) -> String {
    let mut rows = String::from("| Field | Type | Required | Description |\n|---|---|---|---|\n");
    let mut validations = Vec::new();
    collect(schema, root, &mut rows, &mut validations);
    if !validations.is_empty() {
        rows.push_str("\nValidation:\n\n");
        for (path, message) in validations {
            let _ = writeln!(rows, "- {}{}", code(&path), message);
        }
    }
    rows
}

fn collect(schema: &Value, path: &str, rows: &mut String, validations: &mut Vec<(String, String)>) {
    for rule in schema
        .get("x-kubernetes-validations")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        if let Some(message) = rule.get("message").and_then(Value::as_str) {
            validations.push((path.to_owned(), message.to_owned()));
        }
    }
    if let Some(items) = schema.get("items") {
        collect(items, &format!("{path}[]"), rows, validations);
        return;
    }
    let required = names(schema.get("required"));
    let Some(properties) = schema.get("properties").and_then(Value::as_object) else {
        return;
    };
    for (name, property) in properties {
        let child = if path.is_empty() {
            name.clone()
        } else {
            format!("{path}.{name}")
        };
        let _ = writeln!(
            rows,
            "| `{child}` | {} | {} | {} |",
            kind(property),
            if required.contains(&name.as_str()) {
                "yes"
            } else {
                ""
            },
            description(property),
        );
        collect(property, &child, rows, validations);
    }
}

fn code(path: &str) -> String {
    if path.is_empty() {
        String::new()
    } else {
        format!("`{path}`: ")
    }
}

fn kind(schema: &Value) -> String {
    let base = if schema.get("x-kubernetes-int-or-string").is_some() {
        "int-or-string".to_owned()
    } else {
        schema
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or("any")
            .to_owned()
    };
    match base.as_str() {
        "array" => format!(
            "[]{}",
            schema.get("items").map_or_else(|| "any".to_owned(), kind)
        ),
        "object" => match schema.get("additionalProperties") {
            Some(Value::Object(values)) if schema.get("properties").is_none() => {
                format!("map[string]{}", kind(&Value::Object(values.clone())))
            }
            _ => "object".to_owned(),
        },
        _ => match schema.get("format").and_then(Value::as_str) {
            Some(format) => format!("{base} ({format})"),
            None => base,
        },
    }
}

fn description(schema: &Value) -> String {
    let mut parts = Vec::new();
    if let Some(text) = schema.get("description").and_then(Value::as_str) {
        let text = text.split_whitespace().collect::<Vec<_>>().join(" ");
        if !is_type_name(&text) {
            parts.push(text);
        }
    }
    if let Some(values) = schema.get("enum").and_then(Value::as_array) {
        let values: Vec<String> = values
            .iter()
            .map(|value| format!("`{}`", plain(value)))
            .collect();
        parts.push(format!("One of {}.", values.join(", ")));
    }
    if let Some(default) = schema.get("default") {
        parts.push(format!("Default `{}`.", plain(default)));
    }
    let bound = |key: &str| schema.get(key).and_then(Value::as_f64);
    match (bound("minimum"), bound("maximum")) {
        (Some(min), Some(max)) => parts.push(format!("Range {min}–{max}.")),
        (Some(min), None) => parts.push(format!("Minimum {min}.")),
        (None, Some(max)) => parts.push(format!("Maximum {max}.")),
        (None, None) => {}
    }
    if let Some(length) = schema.get("maxLength") {
        parts.push(format!("Maximum length {length}."));
    }
    if let Some(pattern) = schema.get("pattern").and_then(Value::as_str) {
        parts.push(format!("Pattern `{pattern}`."));
    }
    parts.join(" ").replace('|', "\\|")
}

fn is_type_name(text: &str) -> bool {
    text.len() > 2
        && text.starts_with('`')
        && text.ends_with('`')
        && text[1..text.len() - 1].chars().all(char::is_alphanumeric)
}

fn plain(value: &Value) -> String {
    match value {
        Value::String(text) => text.clone(),
        other => other.to_string(),
    }
}
